import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const GuiYeuCauBaoTri = () => {
    const now = new Date();
    const [selectedDate, setSelectedDate] = useState(now.getDate());
    const [selectedMonth, setSelectedMonth] = useState(now.getMonth() + 1);
    const [selectedYear, setSelectedYear] = useState(now.getFullYear());

    const [userRoom, setUserRoom] = useState('');
    const [title, setTitle] = useState('');
    const [description, setDescription] = useState('');
    const [dailyRequests, setDailyRequests] = useState([]);

    useEffect(() => {
        const profile = JSON.parse(localStorage.getItem('userProfile') || '{}');
        setUserRoom(profile.room_id || profile.room || 'Resident');
        fetchData();
    }, [selectedDate, selectedMonth, selectedYear]);

    const fetchData = () => {
        const allData = JSON.parse(localStorage.getItem('maintenance_db') || '[]');
        const filtered = allData.filter(item => 
            item.day === selectedDate && 
            item.month === selectedMonth && 
            item.year === selectedYear
        );
        setDailyRequests(filtered);
    };

    const handleSendRequest = () => {
        if (!title.trim() || !description.trim()) return alert("Vui lòng điền đủ thông tin!");

        const newRequest = {
            id: Date.now(),
            room: userRoom,
            title: title,
            issue: description,
            status: 'pending',
            day: selectedDate,
            month: selectedMonth,
            year: selectedYear,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        };

        const allData = JSON.parse(localStorage.getItem('maintenance_db') || '[]');
        localStorage.setItem('maintenance_db', JSON.stringify([newRequest, ...allData]));

        setTitle('');
        setDescription('');
        fetchData();
        alert("Gửi yêu cầu thành công!");
    };

    const getStatusText = (status) => {
        if (status === 'pending') return '⏳ Chờ';
        if (status === 'processing') return '🛠 Đang sửa';
        return '✅ Xong';
    };

    return (
        <div style={containerStyle}>
            <div style={headerStyle}>
                <h2 style={{ color: '#fff', margin: 0 }}>🛠 YÊU CẦU BẢO TRÌ</h2>
                <div style={{ display: 'flex', gap: '8px' }}>
                    <select value={selectedDate} onChange={(e) => setSelectedDate(Number(e.target.value))} style={selectSmall}>{Array.from({length:31},(_,i)=><option key={i+1} value={i+1}>{i+1}</option>)}</select>
                    <select value={selectedMonth} onChange={(e) => setSelectedMonth(Number(e.target.value))} style={selectSmall}>{Array.from({length:12},(_,i)=><option key={i+1} value={i+1}>Tháng {i+1}</option>)}</select>
                </div>
            </div>

            <div style={mainLayout}>
                {/* Cột trái: Form nhập */}
                <div style={formCard}>
                    <h3 style={{ color: '#8b5e5e', marginTop: 0 }}>Gửi sự cố phòng {userRoom}</h3>
                    <label style={labelStyle}>Tiêu đề ngắn gọn:</label>
                    <input style={inputStyle} value={title} onChange={(e) => setTitle(e.target.value)} placeholder="VD: Hỏng vòi nước, Cháy bóng đèn..." />

                    <label style={labelStyle}>Mô tả chi tiết:</label>
                    <textarea style={areaStyle} value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Mô tả vị trí sự cố hoặc tình trạng cụ thể..." />

                    <button onClick={handleSendRequest} style={btnStyle}>GỬI YÊU CẦU</button>
                </div>

                {/* Cột phải: Xem chung */}
                <div style={listCard}>
                    <h3 style={{ color: '#8b5e5e', marginTop: 0 }}>Báo cáo ngày {selectedDate}/{selectedMonth}</h3>
                    <div style={{ overflowY: 'auto', flex: 1 }} className="custom-scrollbar">
                        {dailyRequests.length > 0 ? dailyRequests.map(req => (
                            <div key={req.id} style={itemStyle}>
                                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                    <strong style={{fontSize: '15px'}}>P.{req.room}: {req.title}</strong>
                                    <span style={badgeStyle(req.status)}>{getStatusText(req.status)}</span>
                                </div>
                                <p style={{ fontSize: '13px', color: '#666', margin: '5px 0' }}>{req.issue}</p>
                                <div style={{ fontSize: '10px', color: '#999' }}>Gửi lúc: {req.time}</div>
                            </div>
                        )) : <div style={{ textAlign: 'center', marginTop: '40px', color: '#999' }}>Chưa có yêu cầu nào trong ngày này.</div>}
                    </div>
                </div>
            </div>
        </div>
    );
};

// Styles Cư dân
const containerStyle = { flex: 1, display: 'flex', flexDirection: 'column', backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover', borderRadius: '30px', height: 'calc(100vh - 120px)', overflow: 'hidden' };
const headerStyle = { padding: '20px 30px', background: 'rgba(0,0,0,0.4)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' };
const mainLayout = { flex: 1, display: 'flex', gap: '20px', padding: '20px', minHeight: 0 };
const formCard = { width: '320px', background: '#fff', borderRadius: '20px', padding: '20px', display: 'flex', flexDirection: 'column', boxShadow: '0 10px 25px rgba(0,0,0,0.2)' };
const listCard = { flex: 1, background: 'rgba(255,255,255,0.9)', borderRadius: '20px', padding: '20px', display: 'flex', flexDirection: 'column', boxShadow: '0 10px 25px rgba(0,0,0,0.2)' };
const inputStyle = { padding: '12px', borderRadius: '10px', border: '1px solid #ddd', marginBottom: '15px', fontSize: '14px' };
const areaStyle = { ...inputStyle, height: '100px', resize: 'none' };
const labelStyle = { fontSize: '12px', fontWeight: 'bold', color: '#888', marginBottom: '5px' };
const btnStyle = { padding: '15px', borderRadius: '10px', border: 'none', backgroundColor: '#8b5e5e', color: '#fff', fontWeight: 'bold', cursor: 'pointer' };
const selectSmall = { padding: '5px', borderRadius: '8px', border: 'none', fontWeight: 'bold' };
const itemStyle = { padding: '12px', background: '#fff', borderRadius: '12px', marginBottom: '10px', borderLeft: '4px solid #8b5e5e' };
const badgeStyle = (s) => ({ fontSize: '10px', padding: '2px 8px', borderRadius: '10px', fontWeight: 'bold', backgroundColor: s==='pending'?'#ffebeb':s==='processing'?'#fff9db':'#ebffef', color: s==='pending'?'#e03131':s==='processing'?'#f08c00':'#2f9e44' });

export default GuiYeuCauBaoTri;
